    /// C#: `private bool WillLeaveMyHomeDefenseless(int shippedAmountOfForces, int shippedAmountOfSpecialForces)` (Bot_Shipment.cs:72)
    pub fn will_leave_my_home_defenseless(&self, game: &Game, shipped_amount_of_forces: i32, shipped_amount_of_special_forces: i32) -> bool {
        let p = game.player(self.player);
        if game.applicable(Rule::Homeworlds)
            && ((self.faction(game) != Faction::Emperor
                && p.forces_in_reserve()
                    .wrapping_add(p.special_forces_in_reserve())
                    .wrapping_sub(shipped_amount_of_forces)
                    .wrapping_sub(shipped_amount_of_special_forces)
                    <= 3)
                || (self.faction(game) == Faction::Emperor
                    && (p.forces_in_reserve().wrapping_sub(shipped_amount_of_forces) <= 3
                        || p.special_forces_in_reserve().wrapping_sub(shipped_amount_of_special_forces) <= 2)))
        {
            return true;
        }

        false
    }

    /// The filter of `DetermineShipment_ShipDirectlyToSpiceOrDiscoveryAsGuildOrGuildAlly` (both queries), in C# `&&` order.
    fn suitable_for_guild_shipment(&self, game: &Game, l: Location) -> bool {
        self.valid_shipment_locations(game, false, false).cs_contains(&l)
            && self.i_dont_have_advisors_in(game, l)
            && self.total_max_dial_of_opponents(game, l.territory()) <= self.param.shipment_max_enemy_force_strength_fighting_for_spice
            && self.ally_doesnt_block(game, l.territory())
            && !self.storm_will_probably_hit(game, l)
            && self.probably_safe_from_monster(game, l.territory())
    }

