    /// C#: `protected virtual void DetermineShipment_ShipToStrongholdNearSpice()` (Bot_Shipment.cs:213)
    pub fn determine_shipment_ship_to_stronghold_near_spice(&mut self, game: &Game) {
        Self::log_info("DetermineShipment_ShipToStrongholdNearSpice()", vec![]);

        if self.battalion_that_should_be_moved_due_to_ally_presence(game).is_some() {
            return;
        }

        let richest_location = self.richest_location_near_shippable_stronghold_far_from_existing_forces(game);

        if let Some(richest_location) = richest_location {
            let me = self.player;
            let faction = self.faction(game);
            let location_to_ship_to = self.valid_shipment_locations(game, false, false).cs_first_or_default_where(|sh| {
                let sh = *sh;
                (!game.player(me).has_ally()
                    || self.ally(game) == Faction::Ecaz
                    || game.player(self.allied_player(game).or_null()).any_forces_in(Some(sh)) == 0
                    || faction != Faction::Richese
                    || !game.has_low_threshold(Faction::Richese))
                    && !self.in_storm(game, sh)
                    && game.player(me).any_forces_in(Some(sh)) <= 8
                    && sh.is_stronghold()
                    && self.within_range(game, sh, richest_location, &self.sample_battalion(game, sh))
            });

            if let Some(location_to_ship_to) = location_to_ship_to
                && game.player(me).any_forces_in(Some(location_to_ship_to)) < 10
            {
                let forces_needed_for_collection = self.make_even_if_efficient_for_shipping(
                    game,
                    std::cmp::min(6, self.determine_forces_needed_for_collection(game, richest_location)) as f32,
                );
                let opponent = Self::occupying_opponents_in(game, me, richest_location.territory()).into_iter().next();
                let (mut nr_of_forces, mut nr_of_special_forces, mut no_field_value, mut cunning_no_field_value) = (0, 0, 0, 0);
                self.determine_shortage_for_shipment(
                    game,
                    forces_needed_for_collection as f32 + self.total_max_dial_of_opponents(game, richest_location.territory()),
                    false,
                    location_to_ship_to,
                    opponent,
                    game.player(me).forces_in_reserve(),
                    game.player(me).special_forces_in_reserve(),
                    &mut nr_of_forces,
                    &mut nr_of_special_forces,
                    &mut no_field_value,
                    &mut cunning_no_field_value,
                    0,
                    99,
                    faction == Faction::Ixian,
                );

                self.do_shipment_shipment_decision_location_int32_int32_int32_int32_location_bool_bool(
                    game,
                    ShipmentDecision::StrongholdNearResources,
                    location_to_ship_to,
                    nr_of_forces,
                    nr_of_special_forces,
                    no_field_value,
                    cunning_no_field_value,
                    Some(richest_location),
                    true,
                    true,
                );
            }
        }
    }

    /// C#: `protected virtual void DetermineShipment_StrengthenWeakestStronghold(bool onlyIfThreatened, int extraForces, float shortageToAccept, bool takeReinforcementsI...` (Bot_Shipment.cs:245)
    pub fn determine_shipment_strengthen_weakest_stronghold(&mut self, game: &Game, only_if_threatened: bool, extra_forces: i32, shortage_to_accept: f32, take_reinforcements_into_account: bool) {
        Self::log_info("DetermineShipment_StrengthenWeakStronghold()", vec![]);

        let me = self.player;
        // Lazy chain (hazards 16.4): OccupyingOpponentIn in the filter and MaxPotentialForceShortage
        // in the map both draw, element by element.
        let my_weak_strongholds: Vec<(Location, f32)> = self
            .valid_shipment_locations(game, false, false)
            .filter(|s| {
                let s = *s;
                s.is_stronghold()
                    && self.i_dont_have_advisors_in(game, s)
                    && game.player(me).occupying_forces_in_location(s) > 0
                    && self.ally_doesnt_block(game, s.territory())
                    && (!only_if_threatened || self.occupying_opponent_in(game, me, s.territory()).is_some())
                    && !self.in_storm(game, s)
            })
            .map(|s| (s, self.max_potential_force_shortage(game, take_reinforcements_into_account, s)))
            .collect();

        // "MyWeakStrongholds:" + string.Join(",", myWeakStrongholds): pure formatting.
        Self::log_info("MyWeakStrongholds:", vec![]);

        let weakest_stronghold = my_weak_strongholds.into_iter().filter(|s| s.1 > 0.0).highest_or_default(&self.random, |s| s.1);
        Self::log_info("WeakestStronghold:", vec![]);

        if let Some((location, difference)) = weakest_stronghold {
            let opponent = self.opponents(game).into_iter().cs_first_or_default_where(|o| game.player(*o).any_forces_in(Some(location)) > 0);
            let dial_needed = self.make_even_if_efficient_for_shipping(game, difference + extra_forces as f32);
            let (mut nr_of_forces, mut nr_of_special_forces, mut no_field_value, mut cunning_no_field_value) = (0, 0, 0, 0);
            if self.determine_shortage_for_shipment(
                game,
                dial_needed as f32,
                true,
                location,
                opponent,
                game.player(me).forces_in_reserve(),
                game.player(me).special_forces_in_reserve(),
                &mut nr_of_forces,
                &mut nr_of_special_forces,
                &mut no_field_value,
                &mut cunning_no_field_value,
                0,
                0,
                true,
            ) <= shortage_to_accept
            {
                Self::log_info("Shipping to weakest stronghold: ", vec![]);
                self.do_shipment(game, ShipmentDecision::StrengthenWeakStronghold, nr_of_forces, nr_of_special_forces, no_field_value, cunning_no_field_value, location, true, true);
            }
        }
    }

