    /// C#: `protected virtual void DetermineShipment_UnlockMoveBonus(int minResourcesToKeep)` (Bot_Shipment.cs:306)
    pub fn determine_shipment_unlock_move_bonus(&mut self, game: &Game, min_resources_to_keep: i32) {
        let me = self.player;
        if !game.has_ornithopters(me) && game.player(me).any_forces_in(Some(game.map.polar_sink())) > 0 {
            Self::log_info("DetermineShipment_UnlockMoveBonus()", vec![]);

            let target = self
                .valid_shipment_locations(game, false, false)
                .filter(|l| self.i_dont_have_advisors_in(game, *l))
                .filter(|l| {
                    (*l == game.map.arrakeen() && self.ally_doesnt_block_location(game, game.map.arrakeen()))
                        || (*l == game.map.carthag() && self.ally_doesnt_block_location(game, game.map.carthag()))
                })
                .lowest_or_default(&self.random, |l| self.total_max_dial_of_opponents(game, l.territory()));

            if let Some(target) = target {
                let opponent = self.occupying_opponent_in(game, me, target.territory());

                let mut needed = 0.5f32;
                if let Some(opponent) = opponent {
                    let take = self.opponents_to_ship_and_move(game).contains(&opponent);
                    needed = math_max_f32(
                        0.5,
                        self.max_potential_force_shortage(game, take, target) - game.player(me).any_forces_in(Some(game.map.polar_sink())) as f32,
                    );
                }

                let (mut nr_of_forces, mut nr_of_special_forces, mut no_field_value, mut cunning_no_field_value) = (0, 0, 0, 0);
                if self.determine_shortage_for_shipment(
                    game,
                    needed,
                    true,
                    target,
                    opponent,
                    game.player(me).forces_in_reserve(),
                    game.player(me).special_forces_in_reserve(),
                    &mut nr_of_forces,
                    &mut nr_of_special_forces,
                    &mut no_field_value,
                    &mut cunning_no_field_value,
                    min_resources_to_keep,
                    1,
                    false,
                ) <= 0.0
                {
                    self.do_shipment(game, ShipmentDecision::DummyShipment, nr_of_forces, nr_of_special_forces, no_field_value, cunning_no_field_value, target, false, true);
                }
            }
        }
    }

    /// C#: `protected virtual void DetermineShipment_TakeVacantStronghold(int forceStrength, int minResourcesToKeep, int maxUnsupportedForces)` (Bot_Shipment.cs:331)
    pub fn determine_shipment_take_vacant_stronghold(&mut self, game: &Game, force_strength: i32, min_resources_to_keep: i32, max_unsupported_forces: i32) {
        Self::log_info("DetermineShipment_TakeVacantStronghold()", vec![]);

        let me = self.player;
        let map = &game.map;
        let mut target: Option<Location> = None;

        if self.faction(game) == Faction::Ixian && self.vacant_and_valid(game, map.hidden_mobile_stronghold().location()) {
            target = Some(map.hidden_mobile_stronghold().location());
        } else if game.player(me).any_forces_in(Some(map.carthag())) < 8 && self.vacant_and_valid(game, map.arrakeen()) {
            target = Some(map.arrakeen());
        } else if game.player(me).any_forces_in(Some(map.arrakeen())) < 8 && self.vacant_and_valid(game, map.carthag()) {
            target = Some(map.carthag());
        } else if self.vacant_and_valid(game, map.tueks_sietch()) {
            target = Some(map.tueks_sietch());
        } else if self.vacant_and_valid(game, map.habbanya_sietch()) {
            target = Some(map.habbanya_sietch());
        } else if self.vacant_and_valid(game, map.carthag()) {
            target = Some(map.carthag());
        } else if self.vacant_and_valid(game, map.arrakeen()) {
            target = Some(map.arrakeen());
        } else if self.vacant_and_valid(game, map.sietch_tabr()) && (self.last_turn(game) || !game.is_in_storm(map.sietch_tabr())) {
            target = Some(map.sietch_tabr());
        } else if game.is_special_stronghold(map.shield_wall()) {
            let first = map.shield_wall().locations().iter().copied().cs_first();
            if self.vacant_and_valid(game, first) {
                target = Some(map.shield_wall().locations().iter().copied().cs_first());
            } else {
                let last = map.shield_wall().locations().iter().copied().cs_last();
                if self.vacant_and_valid(game, last) {
                    target = Some(map.shield_wall().locations().iter().copied().cs_last());
                }
            }
        }

        if target.is_none() {
            target = self
                .valid_shipment_locations(game, false, false)
                .filter(|l| l.is_stronghold())
                .cs_first_or_default_where(|l| self.vacant_and_valid(game, *l));
        }

        if let Some(target) = target {
            let dial_needed = self.make_even_if_efficient_for_shipping(game, force_strength as f32);
            let (mut nr_of_forces, mut nr_of_special_forces, mut no_field_value, mut cunning_no_field_value) = (0, 0, 0, 0);
            if self.determine_shortage_for_shipment(
                game,
                dial_needed as f32,
                false,
                target,
                None,
                game.player(me).forces_in_reserve(),
                game.player(me).special_forces_in_reserve(),
                &mut nr_of_forces,
                &mut nr_of_special_forces,
                &mut no_field_value,
                &mut cunning_no_field_value,
                min_resources_to_keep,
                max_unsupported_forces,
                true,
            ) <= 2.0
            {
                self.do_shipment(game, ShipmentDecision::VacantStronghold, nr_of_forces, nr_of_special_forces, no_field_value, cunning_no_field_value, target, true, true);
            }
        }
    }

